package quota

import (
	"crypto/rand"
	"errors"
	"fmt"
	"time"

	agentmeta "miya/internal/agent/catalog"
)

// ResetAttempt identifies one confirmed logical use, including retries after
// an ambiguous network failure. It is never generated by polling.
type ResetAttempt struct {
	Agent                           string `json:",omitempty"`
	Key, CreditID, AccountKey, Home string
}

func NewResetAttempt(r Reading) (ResetAttempt, error) {
	if !agentmeta.UsageFor(r.Agent).UsageReset || r.Resets == nil || r.Resets.AvailableCount <= 0 {
		return ResetAttempt{}, errors.New("No reset cards available. Refresh first.")
	}
	if r.AccountKey == "" || r.Home == "" {
		return ResetAttempt{}, errors.New("The CLI returned no account ID. Update Codex and refresh.")
	}
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		return ResetAttempt{}, errors.New("Unable to create a reset operation. Try again.")
	}
	b[6], b[8] = b[6]&0x0f|0x40, b[8]&0x3f|0x80
	a := ResetAttempt{Agent: r.Agent, Key: fmt.Sprintf("%x-%x-%x-%x-%x", b[:4], b[4:6], b[6:8], b[8:10], b[10:]), AccountKey: r.AccountKey, Home: r.Home}
	// Name the soonest card only when all counted cards are listed. Otherwise
	// leave selection to Codex rather than claim an incomplete list is complete.
	if len(r.Resets.Credits) == r.Resets.AvailableCount {
		cards := *r.Resets
		cards.Normalize(time.Now())
		if len(cards.Credits) == cards.AvailableCount {
			a.CreditID = cards.Credits[0].ID
		}
	}
	return a, nil
}

type ResetResult struct {
	Outcome string
	Reading Reading
}
